import unittest
from candidate import intersperse

class TestIntersperse(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(intersperse([], 4), [])

    def test_single_element(self):
        self.assertEqual(intersperse([5], 0), [5])

    def test_normal_case_multiple_elements(self):
        self.assertEqual(intersperse([1, 2, 3], 4), [1, 4, 2, 4, 3])

    def test_normal_case_with_negative_numbers(self):
        self.assertEqual(intersperse([-1, -2, -3], 0), [-1, 0, -2, 0, -3])

    def test_normal_case_with_floats(self):
        self.assertEqual(intersperse([1.5, 2.5, 3.5], 0.5), [1.5, 0.5, 2.5, 0.5, 3.5])

    def test_delimeter_at_start_and_end(self):
        self.assertEqual(intersperse([1, 2, 3], 1), [1, 1, 2, 1, 3])

    def test_boundary_case_two_elements(self):
        self.assertEqual(intersperse([10, 20], 5), [10, 5, 20])

    def test_boundary_case_last_element_only(self):
        self.assertEqual(intersperse([10], 5), [10])

    def test_boundary_case_first_element_only(self):
        self.assertEqual(intersperse([10, 20, 30], 5)[0:2], [10, 5])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            intersperse(None, 4)

    def test_none_delimeter(self):
        with self.assertRaises(TypeError):
            intersperse([1, 2, 3], None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            intersperse("not a list", 4)

    def test_non_int_delimeter(self):
        with self.assertRaises(TypeError):
            intersperse([1, 2, 3], "delimeter")

    def test_list_with_non_integer_elements(self):
        with self.assertRaises(TypeError):
            intersperse([1, "two", 3], 4)

    def test_large_input(self):
        large_list = list(range(1, 101))
        expected = [1] + [4] * 100 + [100]
        self.assertEqual(intersperse(large_list, 4), expected)

    def test_mixed_types_with_valid_delimeter(self):
        with self.assertRaises(TypeError):
            intersperse([1, "two", 3], 4)

    def test_delimeter_equals_first_element(self):
        self.assertEqual(intersperse([4, 5, 6], 4), [4, 4, 5, 4, 6])

    def test_delimeter_equals_last_element(self):
        self.assertEqual(intersperse([1, 2, 4], 4), [1, 4, 2, 4, 4])
